}

export interface Notification {
    id: string;
    userId: string;
    message: string;
    read: boolean;
    createdAt: string; // ISO date string
}

type EventCallback = (payload: any) => void;

export class EventBus {
    private subscribers: Map<string, EventCallback[]> = new Map();

    public subscribe(event: string, callback: EventCallback): void {
        if (!this.subscribers.has(event)) {
            this.subscribers.set(event, []);
        }
        this.subscribers.get(event)?.push(callback);
    }

    public publish(event: string, payload: any): void {
        if (this.subscribers.has(event)) {
            this.subscribers.get(event)?.forEach(callback => {
                // Run callbacks asynchronously to prevent blocking the publisher
                // and to adhere to the decoupled nature of event buses.
                setImmediate(() => callback(payload));
            });
        }
    }
}

import { User, CreateUserInput, UpdateUserInput } from '../models';
import { randomUUID } from 'crypto';

export class UserService {
    private users: Map<string, User> = new Map();

    constructor() {
        // Seed with a default user
        const defaultUser: User = {
            id: randomUUID(),
            name: "John Doe",
            email: "john.doe@example.com"
        };
        this.users.set(defaultUser.id, defaultUser);
    }

    public async listUsers(): Promise<User[]> {
        return Array.from(this.users.values());
    }

    public async getUser(id: string): Promise<User | undefined> {
        return this.users.get(id);
    }

    public async createUser(input: CreateUserInput): Promise<User> {
        const newUser: User = {
            id: randomUUID(),
            name: input.name,
            email: input.email,
        };
        this.users.set(newUser.id, newUser);
        return newUser;
    }

    public async updateUser(id: string, input: UpdateUserInput): Promise<User | undefined> {
        const user = this.users.get(id);
        if (!user) {
            return undefined;
        }
        if (input.name !== undefined) {
            user.name = input.name;
        }
        if (input.email !== undefined) {
            user.email = input.email;
        }
        this.users.set(id, user);
        return user;
    }

    public async deleteUser(id: string): Promise<boolean> {
        return this.users.delete(id);
    }
}

import { Project, CreateProjectInput, UpdateProjectInput } from '../models';
import { randomUUID } from 'crypto';

export class ProjectService {
    private projects: Map<string, Project> = new Map();

    public async listProjects(): Promise<Project[]> {
        return Array.from(this.projects.values());
    }

    public async getProject(id: string): Promise<Project | undefined> {
        return this.projects.get(id);
    }

    public async createProject(input: CreateProjectInput): Promise<Project> {
        const newProject: Project = {
            id: randomUUID(),
            name: input.name,
            description: input.description,
            memberIds: [],
        };
        this.projects.set(newProject.id, newProject);
        return newProject;
    }

    public async updateProject(id: string, input: UpdateProjectInput): Promise<Project | undefined> {
        const project = this.projects.get(id);
        if (!project) {
            return undefined;
        }
        if (input.name !== undefined) {
            project.name = input.name;
        }
        if (input.description !== undefined) {
            project.description = input.description;
        }
        this.projects.set(id, project);
        return project;
    }

    public async deleteProject(id: string): Promise<boolean> {
        return this.projects.delete(id);
    }

    public async addMemberToProject(projectId: string, userId: string): Promise<Project | undefined> {
        const project = this.projects.get(projectId);
        if (!project) {
            return undefined;
        }
        if (!project.memberIds.includes(userId)) {
            project.memberIds.push(userId);
        }
        this.projects.set(projectId, project);
        return project;
    }

    public async removeMemberFromProject(projectId: string, userId: string): Promise<Project | undefined> {
        const project = this.projects.get(projectId);
        if (!project) {
            return undefined;
        }
        project.memberIds = project.memberIds.filter(memberId => memberId !== userId);
        this.projects.set(projectId, project);
        return project;
    }
}

import { Task, CreateTaskInput, UpdateTaskInput, TaskStatus } from '../models';
import { EventBus } from '../event-bus';
import { randomUUID } from 'crypto';

export class TaskService {
    private tasks: Map<string, Task> = new Map();
    private eventBus: EventBus;

    constructor(eventBus: EventBus) {
        this.eventBus = eventBus;
    }

    public async listTasks(projectId: string): Promise<Task[]> {
        return Array.from(this.tasks.values()).filter(task => task.projectId === projectId);
    }

    public async getTask(id: string): Promise<Task | undefined> {
        return this.tasks.get(id);
    }

    public async createTask(input: CreateTaskInput): Promise<Task> {
        const newTask: Task = {
            id: randomUUID(),
            title: input.title,
            description: input.description,
            status: 'todo', // Initial status
            assigneeId: null,
            projectId: input.projectId,
        };
        this.tasks.set(newTask.id, newTask);
        return newTask;
    }

    public async updateTask(id: string, input: UpdateTaskInput): Promise<Task | undefined> {
        const task = this.tasks.get(id);
        if (!task) {
            return undefined;
        }
        if (input.title !== undefined) {
            task.title = input.title;
        }
        if (input.description !== undefined) {
            task.description = input.description;
        }
        this.tasks.set(id, task);
        return task;
    }

    public async deleteTask(id: string): Promise<boolean> {
        return this.tasks.delete(id);
    }

    public async changeTaskStatus(id: string, newStatus: TaskStatus): Promise<Task | undefined | 'invalid_transition'> {
        const task = this.tasks.get(id);
        if (!task) {
            return undefined;
        }

        const currentStatus = task.status;
        const validTransitions: Record<TaskStatus, TaskStatus[]> = {
            'todo': ['in-progress'],
            'in-progress': ['done'],
            'done': [], // No transitions from done
        };

        if (!validTransitions[currentStatus].includes(newStatus) && newStatus !== currentStatus) {
            return 'invalid_transition';
        }

        if (newStatus !== currentStatus) {
            const oldStatus = task.status;
            task.status = newStatus;
            this.tasks.set(id, task);
            this.eventBus.publish('task.statusChanged', {
                taskId: task.id,
                taskTitle: task.title,
                assigneeId: task.assigneeId,
                oldStatus: oldStatus,
                newStatus: newStatus,
            });
        }

        return task;
    }

    public async assignTask(id: string, assigneeId: string): Promise<Task | undefined> {
        const task = this.tasks.get(id);
        if (!task) {
            return undefined;
        }
        task.assigneeId = assigneeId;
        this.tasks.set(id, task);
        this.eventBus.publish('task.assigned', {
            taskId: task.id,
            taskTitle: task.title,
            assigneeId: assigneeId,
        });
        return task;
    }
}
